	const bisher = Array.isArray(optionen.konflikteBisher) ? optionen.konflikteBisher : [];
	const schluessel = (k) => `${k.feldname}|${String(k.neu).toLowerCase()}`;
	const gesehen = new Set(bisher.map(schluessel));
