	if (offen.length) h.push(`Noch offene Angaben: ${offen.join(', ')}`);
	if (bekannt.length) h.push(`Bereits bekannt (nur angeben, wenn der Kunde sie ausdrücklich nennt oder korrigiert): ${bekannt.join(', ')}`);
